script='''const fixtures=JSON.parse(document.getElementById('fixture-data').textContent);let selected=0;const el=id=>document.getElementById(id);function save(name,obj){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function paint(){const f=fixtures[selected],player=el('audience').value==='player';el('title').textContent=f.fixtureId+' · '+f.title;el('purpose').textContent=f.purpose+' · '+f.levels.length+' level(s) · native revision '+f.revision;el('zoom').disabled=player;el('render').src=player?f.player:f.images[el('zoom').value];el('render').alt=f.title+' — '+(player?'static player export':'GM artwork baseline');el('caption').textContent=player?'Existing static export filter; unreviewed dressing omitted. This is not a live player session.':'Native GM artwork at zoom '+el('zoom').value+'; 800×520, DPR1; gameplay and specialty overlays omitted.';el('details').textContent=JSON.stringify({nativeId:f.nativeId,catalogId:f.catalogId,levels:f.levels,privateFeatureExpectations:f.secrets,nativeFile:f.nativeFile,notes:f.notes},null,2);for(const b of document.querySelectorAll('[data-fixture]'))b.setAttribute('aria-current',String(Number(b.dataset.fixture)===selected));}for(const[f,i]of fixtures.map((f,i)=>[f,i])){const b=document.createElement('button');b.type='button';b.dataset.fixture=i;b.textContent=f.fixtureId+' · '+f.purpose;b.onclick=()=>{selected=i;paint()};el('nav').append(b)}el('audience').onchange=paint;el('zoom').onchange=paint;el('native').onclick=()=>save(fixtures[selected].fixtureId+'.native-map.json',fixtures[selected].native);el('roles').onclick=()=>save(fixtures[selected].fixtureId+'.role-expectations.json',fixtures[selected].roleExpectations);paint();'''
